      return num(`שופכים ${L} ליטר מים למכל ריק בצורת תיבה, שהבסיס שלו ${a} × ${b} ס"מ. לאיזה גובה יגיעו המים?`, h, { fig: { svg: S3.tankSVG(a, b, Math.ceil(h * 1.4), 0, { lw: false }) }, unit: 'ס"מ', traps: [[L / (a * b), 'קודם הופכים ליטרים לסמ"ק (× 1,000), ורק אז מחלקים בשטח הבסיס.'], [L, 'ליטרים הם לא סנטימטרים. הופכים לסמ"ק ומחלקים בשטח הבסיס.'], [V / a, 'מחלקים בשטח הבסיס (אורך × רוחב), לא רק באורך.']].filter(([v]) => v !== h), hint: 'גובה המים = נפח המים : שטח הבסיס. קודם הופכים ליטרים לסמ"ק.', exp: `${L} ליטר = ${fmt(V)} ${U3}. שטח הבסיס ${M(`${a} × ${b} = ${a * b}`)}. הגובה: ${M(`${fmt(V)} : ${a * b} = ${h}`)} ס"מ`, skill: 'l4f', steps: [{ p: `${L} ליטר = כמה סמ"ק?`, a: V }, { p: 'שטח הבסיס:', a: a * b }, { p: 'גובה המים:', a: h }], help: { tank: [a, b, Math.ceil(h * 1.4), h] } });
